var sumGame = function(num) {
    const n = num.length;
    const halfLen = n / 2;

    const sum = [0, 0];
    const quest = [0, 0];

    for (let i = 0; i < n; i++) {
        const pos = i < halfLen ? 0 : 1;

        if (num[i] !== '?') {
            sum[pos] += Number(num[i]);
            continue;
        }

        if (quest[pos] === 0) {
            quest[pos]++;
            continue;
        }

        sum[pos] += 9;
        quest[pos]--;
    }

    if (quest[0] !== quest[1]) {
        return true;
    }

    return sum[0] !== sum[1];
};

